    var ctrl = new AbortController(), timer = setTimeout(function () { ctrl.abort(); }, 6000);
    try { var res = await fetch(url, { signal: ctrl.signal, credentials: 'omit' }); if (!res.ok) throw new Error('Reviews unavailable'); return validate(await res.json()); }
    finally { clearTimeout(timer); }
