          var label = more.querySelector('.v2-btn__label') || more; label.textContent = expanded ? 'Show fewer reviews' : 'Show more reviews';
          Array.from(list.children).forEach(function (item, i) { item.hidden = !expanded && i >= initial; });
          checkClamps(widget);
