  var btn = doc.getElementById('v2-menu-btn');
  var menu = doc.getElementById('v2-menu');
  var label = btn ? btn.querySelector('[data-v2-menu-label]') : null;
  var wide = window.matchMedia ? window.matchMedia('(min-width:1080px)') : null;
  var inerted = [];                       /* elements this script made inert, so close() restores exactly those */

  function reduced() { return V2.reducedMotion ? V2.reducedMotion() : false; }
