/* ===== js/110-process.js ===== */
/* Original vertical timeline behaviour, scoped and responsive to live motion preferences. */
(function(){
  const rail=document.querySelector('#v2-process-rail');
  if(!rail)return;
  const orb=rail.querySelector('.p90-orb');
  const steps=[...rail.querySelectorAll('.p90-step')];
  const preference=window.matchMedia('(prefers-reduced-motion: reduce)');
  let scheduled=false;
  function paint(){
    scheduled=false;
    const reduced=preference.matches;
    const box=rail.getBoundingClientRect();
    const viewport=window.innerHeight;
    const maximum=document.documentElement.scrollHeight-viewport;
    let progress=reduced?1:Math.max(0,Math.min(1,(viewport*.58-box.top)/Math.max(1,box.height)));
    if(maximum>0&&window.scrollY>=maximum-2)progress=1;
    rail.style.setProperty('--p90-fill',progress.toFixed(4));
    rail.classList.toggle('is-drawing',!reduced&&progress>.002&&progress<.999);
    if(orb)orb.style.top=(progress*box.height).toFixed(1)+'px';
    const head=box.top+progress*box.height;
    steps.forEach(step=>{const node=step.querySelector('.p90-node').getBoundingClientRect();step.classList.toggle('passed',reduced||head>=node.top+node.height/2-1);});
  }
  function schedule(){if(scheduled)return;scheduled=true;requestAnimationFrame(paint);}
  window.addEventListener('scroll',schedule,{passive:true});
  window.addEventListener('resize',schedule,{passive:true});
  preference.addEventListener('change',schedule);
  if('ResizeObserver' in window)new ResizeObserver(schedule).observe(rail);
  document.fonts?.ready.then(schedule);
  paint();
})();

