// Static previews keep form controls disabled until the no-send controller is ready.
(function () {
  if (document.documentElement.dataset.v2Preview !== 'static') return;
  document.querySelectorAll('[data-v2-form]').forEach(function (form) {
    if (!form.__v2Form) return;
    form.querySelectorAll('[data-v2-preview-control]').forEach(function (control) {
      control.disabled = false;
    });
  });
})();
